using System;
using UnityEngine;

namespace Simulator.Web
{
    /// <summary>Map scenes included in the player, by assetGuid. Generated by BuiltinMapBuild.</summary>
    public class BuiltinMapCatalog : ScriptableObject
    {
        [Serializable]
        public class Entry
        {
            public string assetGuid, name, scenePath;
        }
        public Entry[] maps = Array.Empty<Entry>();
    }
}
